import{o as i,c as r,a0 as n,j as e,t as s,p as l}from"./chunks/framework.L_oL6aia.js";const u={class:"rock-copy-email-wrapper inline"},m=JSON.parse('{"title":"About - Main St Audio Labs","description":"","frontmatter":{"layout":"doc","sidebar":false,"aside":false,"title":"About - Main St Audio Labs"},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),d={name:"about.md"},b=Object.assign(d,{setup(h){const t=l("Copy Email");function o(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),t.value="Copied!",setTimeout(function(){t.value="Copy Email"},2e3)}return(c,a)=>(i(),r("div",null,[a[1]||(a[1]=n('<h1 id="about-main-st-audio-labs" tabindex="-1">About Main St Audio Labs <a class="header-anchor" href="#about-main-st-audio-labs" aria-label="Permalink to &quot;About Main St Audio Labs&quot;">​</a></h1><p>Main St Audio Labs is a personal project born at the intersection of vintage rock &#39;n&#39; roll passion, analog modeling, and software engineering.</p><hr><h2 id="the-story-behind-the-labs" tabindex="-1">The Story Behind the Labs <a class="header-anchor" href="#the-story-behind-the-labs" aria-label="Permalink to &quot;The Story Behind the Labs&quot;">​</a></h2><p>Main St Audio Labs was founded by <strong>Emiliano Tegli</strong>, a guitarist, developer, and tone enthusiast obsessed with the raw, dynamic, and touch-sensitive guitar sounds of the late 1960s and early 1970s.</p><p>The name is a direct tribute to the legendary basement sessions of the Rolling Stones&#39; <em>Exile on Main St.</em>—an era where records were greasy, valves were pushed to their melting point, and guitar tones had a tridimensional, organic warmth that defined rock music.</p><hr><h2 id="why-main-st-audio-labs" tabindex="-1">Why Main St Audio Labs? <a class="header-anchor" href="#why-main-st-audio-labs" aria-label="Permalink to &quot;Why Main St Audio Labs?&quot;">​</a></h2><p>Modern audio plugins have become incredibly powerful, but they often get in the way of making music. Musicians and producers are frequently forced to navigate infinite parameters, coordinate complex routings, scroll through hundreds of presets, and deal with bloated setups that drain CPU resources.</p><p>We believe in a different approach: <strong>The Simplicity Manifesto.</strong></p><h3 id="📻-1-calibrated-to-the-records-mix-ready" tabindex="-1">📻 1. Calibrated to the Records (Mix-Ready) <a class="header-anchor" href="#📻-1-calibrated-to-the-records-mix-ready" aria-label="Permalink to &quot;📻 1. Calibrated to the Records (Mix-Ready)&quot;">​</a></h3><p>Instead of giving you raw, unpolished emulations and leaving you to struggle with post-equalization, we do the heavy lifting beforehand. Each plugin is meticulously tuned and calibrated by studying the exact guitar, synth, and dynamic responses heard on classic studio albums and live records, ensuring they fit immediately into your mix.</p><h3 id="⚡-2-ultra-low-cpu-maximum-performance" tabindex="-1">⚡ 2. Ultra-Low CPU &amp; Maximum Performance <a class="header-anchor" href="#⚡-2-ultra-low-cpu-maximum-performance" aria-label="Permalink to &quot;⚡ 2. Ultra-Low CPU &amp; Maximum Performance&quot;">​</a></h3><p>We believe your computer should focus on your music, not on running heavy graphics or inefficient DSP loops. All of our tools are built using highly optimized audio engines and lightweight DSP code that deliver maximum performance with an extremely low CPU footprint, letting you run multiple instances without breaking a sweat.</p><hr><h2 id="our-mission" tabindex="-1">Our Mission <a class="header-anchor" href="#our-mission" aria-label="Permalink to &quot;Our Mission&quot;">​</a></h2><p>To build virtual boutique audio tools that sound raw, feel organic, and get completely out of the way of your inspiration.</p><p>No registration walls, no bloated setups—just plug in, turn the knobs, and play.</p><hr><h2 id="contact-amp-feedback" tabindex="-1">Contact &amp; Feedback <a class="header-anchor" href="#contact-amp-feedback" aria-label="Permalink to &quot;Contact &amp;amp; Feedback&quot;">​</a></h2><p>We are always listening. If you have any suggestions, audio tracks you want to share, or custom cabinet requests, feel free to copy our email below:</p>',21)),e("div",u,[a[0]||(a[0]=e("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),e("button",{class:"rock-copy-btn",onClick:o},s(t.value),1)]),a[2]||(a[2]=e("p",{style:{"margin-top":"2rem","margin-bottom":"1rem"}},"If you would like to support our independent research and help us keep our plugins free, you can support us with Card, PayPal, or Cryptocurrency:",-1)),a[3]||(a[3]=e("div",null,[e("a",{href:"/support",class:"rock-btn rock-btn-primary",style:{display:"inline-block","text-align":"center"}},"Support the Lab (Ko-fi / Crypto) ☕")],-1))]))}});export{m as __pageData,b as default};
